import{_ as t,o as r,c as n,a2 as i}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Falsche Werte und bekannte Fehler älterer Versionen","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/04.fehlerbehebung/02.falsche-werte-und-bekannte-fehler.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/fehlerbehebung/falsche-werte-und-bekannte-fehler.md","filePath":"de/adapter/sourceanalytix/fehlerbehebung/falsche-werte-und-bekannte-fehler.md","lastUpdated":null}'),a={name:"de/adapter/sourceanalytix/fehlerbehebung/falsche-werte-und-bekannte-fehler.md"};function s(d,e,o,l,h,u){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="falsche-werte-und-bekannte-fehler-alterer-versionen" tabindex="-1">Falsche Werte und bekannte Fehler älterer Versionen <a class="header-anchor" href="#falsche-werte-und-bekannte-fehler-alterer-versionen" aria-label="Permalink to &quot;Falsche Werte und bekannte Fehler älterer Versionen&quot;">​</a></h1><p><a id="values-costs-far-too-high"></a></p><h2 id="werte-oder-kosten-viel-zu-hoch-oder-negativ-–-stimmt-die-einheit" tabindex="-1">Werte oder Kosten viel zu hoch oder negativ – stimmt die Einheit? <a class="header-anchor" href="#werte-oder-kosten-viel-zu-hoch-oder-negativ-–-stimmt-die-einheit" aria-label="Permalink to &quot;Werte oder Kosten viel zu hoch oder negativ – stimmt die Einheit?&quot;">​</a></h2><p><strong>Kurz:</strong> Meist passt eine Einheit nicht: Bei der Quelle ist eine andere Einheit gewählt, als das Gerät liefert, der Preis steht nicht je Einheit der Preisdefinition, oder ein Startwert ist in der falschen Einheit eingetragen. Prüfe diese Stellen in der Detailansicht der Quelle und korrigiere danach die Werte.</p><h3 id="die-haufigsten-ursachen" tabindex="-1">Die häufigsten Ursachen <a class="header-anchor" href="#die-haufigsten-ursachen" aria-label="Permalink to &quot;Die häufigsten Ursachen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Was falsch ist</th><th>Was du siehst</th><th>Richtig</th></tr></thead><tbody><tr><td>Einheit der Quelle <code>kWh</code>, das Gerät liefert aber <code>Wh</code></td><td>Alle Werte sind 1.000-mal zu groß</td><td>Die Einheit, die das Gerät liefert</td></tr><tr><td>Leistung und Energie verwechselt, zum Beispiel <code>kW</code> statt <code>kWh</code></td><td>Ein Zählerstand wird wie eine Leistung über die Zeit aufsummiert, die Werte wachsen viel zu schnell</td><td>Zählerstand mit Energie-Einheit (<code>kWh</code>), Leistung mit <code>W</code> oder <code>kW</code></td></tr><tr><td>„Preis pro Einheit“ in Cent statt Euro, zum Beispiel <code>28.5</code> statt <code>0.285</code></td><td>Kosten 100-mal zu hoch</td><td>Preis je Einheit der Preisdefinition, also je kWh oder je m³</td></tr><tr><td>Startwert in <code>Wh</code>, die Preisdefinition rechnet in <code>kWh</code></td><td>Verbrauch stark negativ</td><td>Startwert in der Zieleinheit</td></tr></tbody></table><p>Die Begriffe Zieleinheit, Gesamtstand und Startwert sind unter <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Die Begriffe</a> erklärt.</p><h3 id="so-prufst-du-es-ab-v0-7-0" tabindex="-1">So prüfst du es (ab v0.7.0) <a class="header-anchor" href="#so-prufst-du-es-ab-v0-7-0" aria-label="Permalink to &quot;So prüfst du es (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne unter „Instanzen“ die Einstellungen der SourceAnalytix-Instanz und im Tab „Übersicht“ deine Quelle.</li><li>Lies oben „Art“: Dort steht zum Beispiel „Zählerstand · kWh“ oder „Leistung · W → kWh“. Das ist die Messart und die Zieleinheit. Vergleiche den „Gesamtstand“ mit deinem Zähler.</li><li>Prüfe unter „Einstellungen“ das Feld „Einheit“. Es muss die Einheit sein, die das Gerät liefert. Hinter der „Preisdefinition“ steht deren Einheit in Klammern.</li><li>Prüfe im Tab „Preisdefinitionen“ den „Preis pro Einheit“ der gewählten Kategorie.</li><li>Schau in den Tab „Probleme“. Ein unpassender Startwert steht dort als „Startwert passt nicht“.</li></ol><p>Startwerte prüft SourceAnalytix ab v0.7.0 schon bei der Eingabe. Passt ein Startwert erst geteilt durch 1000, fragt das Feld „Sieht nach Wh aus – gemeint … ?“. Mehr dazu unter <a href="./../erste-schritte/erster-zaehler#start-values-unit">Was trage ich bei den Startwerten ein?</a>.</p><h3 id="werte-reparieren" tabindex="-1">Werte reparieren <a class="header-anchor" href="#werte-reparieren" aria-label="Permalink to &quot;Werte reparieren&quot;">​</a></h3><p>Werte, die schon geschrieben sind, korrigiert SourceAnalytix nicht von selbst, wenn du die Einheit änderst. Bring danach den Gesamtstand mit der Aktion „Zählerstand angleichen“ auf den Stand deines Zählers und rechne die Kosten mit „Kosten ab Datum neu rechnen“ neu. Wie du Verbrauch in laufenden und abgeschlossenen Perioden reparierst, steht unter <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a>.</p><h3 id="es-entsteht-gar-kein-ordner-auch-kein-jahresordner" tabindex="-1">Es entsteht gar kein Ordner, auch kein Jahresordner <a class="header-anchor" href="#es-entsteht-gar-kein-ordner-auch-kein-jahresordner" aria-label="Permalink to &quot;Es entsteht gar kein Ordner, auch kein Jahresordner&quot;">​</a></h3><p>Erkennt SourceAnalytix die Einheit gar nicht, startet es die Quelle nicht und legt keine States an, also auch keinen Jahresordner. Das ist unter <a href="./log-meldungen#error-unit-not-supported-no">Fehler „unit not supported“ / „No unit defined“</a> beschrieben.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Welche Einheit stelle ich am Datenpunkt ein?</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#values-negative-after-entering-start">Negative Werte nach Startwerten</a> · <a href="./../referenz/einstellungen#price-definition-structured-categories-base">Wie ist eine Preisdefinition aufgebaut?</a></p><p><a id="after-update-restore-values-0"></a></p><h2 id="nach-update-oder-restore-sind-werte-0-oder-sourceanalytix-fehlt" tabindex="-1">Nach Update oder Restore sind Werte 0 oder SourceAnalytix fehlt <a class="header-anchor" href="#nach-update-oder-restore-sind-werte-0-oder-sourceanalytix-fehlt" aria-label="Permalink to &quot;Nach Update oder Restore sind Werte 0 oder SourceAnalytix fehlt&quot;">​</a></h2><p><strong>Kurz:</strong> Nach einem Restore fehlt oft der Adapter selbst, denn ein Backup sichert Einstellungen und Daten, nicht den Programmcode. Installiere SourceAnalytix dann aus dem Repository „latest“ neu. Sind danach Werte 0 oder passt der Gesamtstand nicht zum Zähler, gleichst du ihn ab v0.7.0 mit „Zählerstand angleichen“ an.</p><h3 id="sourceanalytix-fehlt-nach-dem-restore" tabindex="-1">SourceAnalytix fehlt nach dem Restore <a class="header-anchor" href="#sourceanalytix-fehlt-nach-dem-restore" aria-label="Permalink to &quot;SourceAnalytix fehlt nach dem Restore&quot;">​</a></h3><p>Meldet der Restore zum Beispiel „Unknown packetName“ oder startet die Instanz nicht, ist der Adapter nicht installiert. SourceAnalytix liegt nur im Repository „latest“ (Beta). Stelle das Repository um und installiere SourceAnalytix wie unter <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Wie aktualisiere ich SourceAnalytix?</a> beschrieben. Die gesicherte Instanz mit ihren Daten läuft danach weiter.</p><h3 id="werte-0-oder-fehler-nach-update-oder-restore" tabindex="-1">Werte 0 oder Fehler nach Update oder Restore <a class="header-anchor" href="#werte-0-oder-fehler-nach-update-oder-restore" aria-label="Permalink to &quot;Werte 0 oder Fehler nach Update oder Restore&quot;">​</a></h3><p>Ein Update ändert deine Werte nicht. Nach einem Restore können aber der Gesamtstand im State <code>cumulativeReading</code> und der Offset in den Einstellungen des Datenpunkts aus verschiedenen Zeitpunkten stammen. Dann passt der Gesamtstand nicht mehr zum Zähler.</p><p>So prüfst du es (ab v0.7.0):</p><ol><li>Öffne in den Instanz-Einstellungen im Tab „Übersicht“ die Quelle und vergleiche den „Gesamtstand“ mit deinem Zähler. Den Offset siehst du unter „Für Experten“ als <code>valueAtDeviceReset</code>.</li><li>Stimmt der Gesamtstand nicht, wähle bei „Aktionen“ den Eintrag „Zählerstand angleichen“ und trage den Stand ein, den dein Zähler zeigt.</li><li>Schau in den Tab „Probleme“. „Periodenwechsel verpasst“ holst du mit „Nachholen“ nach.</li></ol><p><strong>Bis v0.6.1</strong> startet eine Quelle nicht, wenn der Offset größer als der Gesamtstand ist. Im Log steht dann „Check settings for … Known valueAtDeviceReset …“. Ab v0.6.2 läuft sie weiter. Was dann zu tun ist, steht unter <a href="./log-meldungen#error-known-valueatdevicereset-known-cumulative">Fehler „Known valueAtDeviceReset &gt; known cumulative value“</a>.</p><p><strong>Bis v0.6.x:</strong> Den Offset siehst du nur im Objekt des Datenpunkts unter <code>common.custom.sourceanalytix.0</code> als <code>valueAtDeviceReset</code>. Wie du ihn und den Gesamtstand von Hand passend setzt, steht unter <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Ziehst du auf ein neues System um, nimm ein Vollbackup und spiel es nicht um Mitternacht ein. Dann bleiben Gesamtstand und Einstellungen beieinander.</p></div><p><strong>Siehe auch:</strong> <a href="./../anleitungen/betrieb-und-wartung#data-back-up-move-new">Wo liegen die Daten, wie sichere ich sie?</a> · <a href="./../anleitungen/betrieb-und-wartung#iobroker-was-down-midnight-recover">ioBroker war über Mitternacht aus</a></p><p><a id="costs-stay-0-not-calculated"></a></p><h2 id="kosten-bleiben-0-oder-werden-nicht-berechnet" tabindex="-1">Kosten bleiben 0 oder werden nicht berechnet <a class="header-anchor" href="#kosten-bleiben-0-oder-werden-nicht-berechnet" aria-label="Permalink to &quot;Kosten bleiben 0 oder werden nicht berechnet&quot;">​</a></h2><p><strong>Kurz:</strong> Kosten entstehen nur, wenn bei der Quelle „Kosten“ angehakt ist und die Preisdefinition einen gültigen „Preis pro Einheit“ hat. Prüfe außerdem die „Kostenart“ der Preisdefinition: Bei „Erträge“ stehen die Werte unter <code>earnings</code>, nicht unter <code>costs</code>.</p><h3 id="checkliste-ab-v0-7-0" tabindex="-1">Checkliste (ab v0.7.0) <a class="header-anchor" href="#checkliste-ab-v0-7-0" aria-label="Permalink to &quot;Checkliste (ab v0.7.0)&quot;">​</a></h3><ol><li><strong>„Kosten“ angehakt?</strong> Öffne die Quelle und prüfe unter „Einstellungen“ den Haken „Kosten“. Ohne ihn legt SourceAnalytix keinen Ordner <code>costs</code> oder <code>earnings</code> an. Ändern, „Übernehmen“.</li><li><strong>Preisdefinition gewählt und passend?</strong> Fehlt sie oder passt ihre Einheit nicht, steht die Quelle im Tab „Probleme“ (siehe <a href="./log-meldungen#error-no-cost-type-defined">Fehler „No cost type defined“</a>).</li><li><strong>Gültiger Preis?</strong> Prüfe im Tab „Preisdefinitionen“ den „Preis pro Einheit“. Ist er keine Zahl, rechnet SourceAnalytix mit 0 und schreibt <code>Price definition &lt;Name&gt; has no valid unit price &lt;Wert&gt;, using 0 to avoid invalid cost calculations</code> ins Log.</li><li><strong>Preis aus einem State?</strong> Liefert der State keinen gültigen Preis, nimmt SourceAnalytix den eingetragenen Ersatzpreis: <code>Price source state &lt;State&gt; for &lt;Name&gt; has no valid value or tariff, using configured fallback price &lt;Preis&gt;</code>. Ist dieser leer, sind die Kosten 0.</li><li><strong>Kosten oder Erträge?</strong> Bei der „Kostenart“ „Erträge“ (Einspeisung) stehen die Werte unter <code>sourceanalytix.0.&lt;Gerät&gt;.currentYear.earnings</code>, der Verbrauch unter <code>currentYear.delivered</code>. In der Detailansicht heißen die Spalten „Einspeisung“ und „Erlös“.</li></ol><p>Für Kosten brauchst du „Zählerstände speichern“ nicht.</p><p>Hast du Preis oder Haken korrigiert, rechnet „Kosten ab Datum neu rechnen“ bei der Quelle die Kosten ab einem Datum mit dem Preisverlauf neu. Der Verbrauch bleibt dabei gleich.</p><p><strong>Bis v0.6.x:</strong> Der Haken heißt im Dialog am Datenpunkt „Kosten berechnen“. Fehlende oder ungültige Preise führen seit v0.5.0 nicht mehr zu ungültigen Kosten, sondern zu 0 mit einer Warnung.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/preise-und-kosten#assign-prices-create-custom-tariffs">Preise zuordnen und eigene Tarife anlegen</a> · <a href="./../anleitungen/preise-und-kosten#costs-recalculated-change-price-change">Werden Kosten bei einer Preisänderung neu berechnet?</a> · <a href="./../anleitungen/quellen-und-einheiten#track-pv-yield-feed-earnings">PV-Ertrag und Einspeisung erfassen</a></p><p><a id="huge-consumption-after-power-outage"></a></p><h2 id="nach-stromausfall-riesiger-verbrauch-bei-leistungsquellen" tabindex="-1">Nach Stromausfall riesiger Verbrauch bei Leistungsquellen <a class="header-anchor" href="#nach-stromausfall-riesiger-verbrauch-bei-leistungsquellen" aria-label="Permalink to &quot;Nach Stromausfall riesiger Verbrauch bei Leistungsquellen&quot;">​</a></h2><p><strong>Kurz:</strong> Bei einer Leistungsquelle gilt der letzte Wert so lange, bis ein neuer kommt. Fällt das Gerät oder das Netz aus, ohne vorher 0 zu melden, rechnet SourceAnalytix die letzte Leistung über die ganze Pause hoch. Ab v0.7.0 verhindert das die Einstellung „Maximale Lücke zwischen Leistungswerten (Minuten)“.</p><h3 id="warum-das-passiert" tabindex="-1">Warum das passiert <a class="header-anchor" href="#warum-das-passiert" aria-label="Permalink to &quot;Warum das passiert&quot;">​</a></h3><p>SourceAnalytix multipliziert jeden Leistungswert mit der Zeit bis zum nächsten Wert. Bis v0.6.x gibt es dafür keine Obergrenze. Kam drei Stunden lang kein Wert, zählen drei Stunden mit der letzten Leistung. War dagegen SourceAnalytix selbst gestoppt, ist der erste Wert nach dem Start nur der neue Ausgangspunkt, und die Pause zählt gar nicht.</p><h3 id="so-beugst-du-vor-ab-v0-7-0" tabindex="-1">So beugst du vor (ab v0.7.0) <a class="header-anchor" href="#so-beugst-du-vor-ab-v0-7-0" aria-label="Permalink to &quot;So beugst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne in den Instanz-Einstellungen von SourceAnalytix im Tab „Übersicht“ die Leistungsquelle.</li><li>Trage im Bereich „Einstellungen“ bei „Maximale Lücke zwischen Leistungswerten (Minuten)“ einen Wert ein, der deutlich größer ist als der längste normale Abstand zwischen zwei Werten deines Geräts.</li><li>Klicke auf „⚡ Übernehmen“. Ein längerer Abschnitt ohne Wert zählt dann als 0. Im Log steht <code>No new power value from &lt;Datenpunkt&gt; for &lt;n&gt; min, longer than the maximum gap of &lt;m&gt; min; this interval is not counted</code>.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Lass die Einstellung leer oder auf 0, wenn dein Gerät nur bei einer Änderung sendet. Sonst fehlt der Verbrauch langer gleichbleibender Abschnitte, zum Beispiel einer Heizung, die stundenlang mit gleicher Leistung läuft.</p></div><p>Kommt von einer Leistungsquelle drei Stunden lang kein Wert, steht sie ab v0.7.0 im Tab „Probleme“ mit „Leistungsquelle meldet seit langem keinen Wert“.</p><p><strong>Bis v0.6.x:</strong> Sorge dafür, dass das Gerät beim Ausschalten 0 meldet, oder nimm einen Zählerstand (kWh) statt der Leistung, wenn das Gerät einen hat (siehe <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Zähler (kWh) oder Leistung (W)?</a>).</p><p>Schon gebuchte Werte reparierst du wie unter <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a> beschrieben.</p><p><strong>Siehe auch:</strong> <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">Wie rechnet SourceAnalytix Watt in kWh um?</a></p><p><a id="so-many-decimals"></a></p><h2 id="warum-so-viele-nachkommastellen" tabindex="-1">Warum so viele Nachkommastellen? <a class="header-anchor" href="#warum-so-viele-nachkommastellen" aria-label="Permalink to &quot;Warum so viele Nachkommastellen?&quot;">​</a></h2><p><strong>Kurz:</strong> SourceAnalytix rundet Verbrauch standardmäßig auf 3 und Kosten auf 2 Nachkommastellen. Jede Quelle hat ihre eigene Einstellung. Ab v0.7.0 änderst du sie in der Detailansicht der Quelle unter „Für Experten“. Mit <code>-1</code> speichert SourceAnalytix den Wert ohne Rundung, dann entstehen viele Nachkommastellen.</p><h3 id="wo-du-die-rundung-einstellst" tabindex="-1">Wo du die Rundung einstellst <a class="header-anchor" href="#wo-du-die-rundung-einstellst" aria-label="Permalink to &quot;Wo du die Rundung einstellst&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ort</th><th>Felder</th><th>Wirkt auf</th></tr></thead><tbody><tr><td>Instanz-Einstellungen, „Haupteinstellungen“, Bereich „Rundung“</td><td>„Nachkommastellen für Verbrauchswerte“ (Standard 3), „Nachkommastellen für Kostenwerte“ (Standard 2)</td><td>nur Quellen, die neu eingerichtet werden</td></tr><tr><td>Detailansicht der Quelle, „Einstellungen“, „Für Experten“ (ab v0.7.0)</td><td>„Nachkommastellen Verbrauch“, „Nachkommastellen Kosten“</td><td>diese Quelle, nach „Übernehmen“</td></tr></tbody></table><p>Bestehende Quellen behalten ihre Rundung, auch wenn du die Vorgabe der Instanz änderst. Seit v0.6.0 speichert jede Quelle ihren eigenen Wert.</p><h3 id="warum-steht-da-402-400" tabindex="-1">Warum steht da 402.400? <a class="header-anchor" href="#warum-steht-da-402-400" aria-label="Permalink to &quot;Warum steht da 402.400?&quot;">​</a></h3><p>SourceAnalytix schreibt eine Zahl, zum Beispiel <code>402.4</code>. Wie viele Stellen, Nullen oder Tausenderpunkte du siehst, legt die Anzeige fest, also VIS, Admin oder deine Visualisierung.</p><p><strong>Bis v0.5.4:</strong> Die Zahl der Nachkommastellen ist nicht einstellbar. Ab v0.5.5 geht das für die Instanz und je Quelle (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/934" target="_blank" rel="noreferrer">#934</a>).</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#instance-settings-exist-periods-decimals">Welche Einstellungen hat die Instanz?</a></p><p><a id="known-bugs-older-versions-please"></a></p><h2 id="bekannte-fehler-alterer-versionen-–-bitte-aktualisieren" tabindex="-1">Bekannte Fehler älterer Versionen – bitte aktualisieren <a class="header-anchor" href="#bekannte-fehler-alterer-versionen-–-bitte-aktualisieren" aria-label="Permalink to &quot;Bekannte Fehler älterer Versionen – bitte aktualisieren&quot;">​</a></h2><p><strong>Kurz:</strong> Viele Fehler aus Forum und Issues sind in neueren Versionen behoben. Prüfe in der Tabelle, ab welcher Version dein Fehler behoben ist, und aktualisiere SourceAnalytix. Bis v0.6.1 gibt es eine Reihe bekannter Fehler, die ab v0.6.2 behoben sind.</p><p>Wie du aktualisierst, steht unter <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Wie aktualisiere ich SourceAnalytix?</a>. SourceAnalytix liegt derzeit nur im Repository „latest“ (Beta).</p><h3 id="bis-v0-6-1-ab-v0-6-2-behoben" tabindex="-1">Bis v0.6.1, ab v0.6.2 behoben <a class="header-anchor" href="#bis-v0-6-1-ab-v0-6-2-behoben" aria-label="Permalink to &quot;Bis v0.6.1, ab v0.6.2 behoben&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fehler bis v0.6.1</th><th>Ab v0.6.2 behoben</th><th>Mehr dazu</th></tr></thead><tbody><tr><td>Ein Zählerstand von genau 0 wird nicht in die Zählerstände (<code>meterReadings</code>) geschrieben.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1253" target="_blank" rel="noreferrer">#1253</a></td><td><a href="./../referenz/states-und-meldungen#meter-readings-cumulative">Zählerstände</a></td></tr><tr><td>Leistungsquellen (W) verlieren an jedem Periodenwechsel die Energie zwischen letztem Wert und Mitternacht.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1254" target="_blank" rel="noreferrer">#1254</a></td><td><a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Zähler oder Leistung?</a></td></tr><tr><td>Zählerstände als Text, zum Beispiel <code>&quot;12,5&quot;</code>, werden nicht berechnet.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1255" target="_blank" rel="noreferrer">#1255</a></td><td><a href="./log-meldungen#source-delivers-text-instead-number">Quelle liefert Text</a></td></tr><tr><td>Im Jahresarchiv überschreiben 29. bis 31. Dezember die Woche 01 des Januars.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1256" target="_blank" rel="noreferrer">#1256</a></td><td><a href="./../hintergrund/perioden-und-zeit#week-52-53-have-values">Woche 52 und 53</a></td></tr><tr><td>„Known valueAtDeviceReset &gt; known cumulative value“: Die Quelle startet nicht.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1257" target="_blank" rel="noreferrer">#1257</a></td><td><a href="./log-meldungen#error-known-valueatdevicereset-known-cumulative">Fehler „Known valueAtDeviceReset“</a></td></tr><tr><td>Meldet ein Gerät zweimal 0 und danach wieder den alten Stand, verdoppelt sich der Gesamtstand.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1258" target="_blank" rel="noreferrer">#1258</a></td><td><a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Reset-Erkennung</a></td></tr><tr><td><code>currentPrice</code> wechselt bei einem künftigen „Gültig ab“ erst nach einem Neustart. Die Kosten sind trotzdem richtig.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1259" target="_blank" rel="noreferrer">#1259</a></td><td><a href="./../referenz/states-und-meldungen#prices-read-written-as-states">Preise als States</a></td></tr><tr><td>War ioBroker über Mitternacht aus, landet der ganze Verbrauch der Lücke im neuen Tag.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1260" target="_blank" rel="noreferrer">#1260</a></td><td><a href="./log-meldungen#midnight-crash-rollover-wrong-time">Mitternacht</a></td></tr><tr><td>Fehler aus dem Programmablauf erscheinen ohne Sentry nicht im Log.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1261" target="_blank" rel="noreferrer">#1261</a></td><td>–</td></tr><tr><td>„Cumulative reading … decreased while reset detection is disabled“ füllt das Log.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1262" target="_blank" rel="noreferrer">#1262</a></td><td><a href="./log-meldungen#high-cpu-memory-use-too">Zu viel Log-Ausgabe</a></td></tr><tr><td>Einheiten wie <code>m3</code> oder <code>kwh</code> am Datenpunkt werden nicht erkannt.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1264" target="_blank" rel="noreferrer">#1264</a></td><td><a href="./log-meldungen#error-unit-not-supported-no">Fehler „No unit defined“</a></td></tr><tr><td><code>km³</code>, <code>dm³</code>, <code>cm³</code>, <code>mm³</code>, <code>µm</code> und <code>nm</code> werden falsch umgerechnet. Unpassende Einheiten fallen erst beim Rechnen auf.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1278" target="_blank" rel="noreferrer">#1278</a></td><td><a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Einheiten</a></td></tr><tr><td>Dauerhaft hohe CPU-Last, weil Quellen bei jeder Objektänderung neu aufgebaut werden.</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1233" target="_blank" rel="noreferrer">#1233</a></td><td><a href="./log-meldungen#high-cpu-memory-use-too">Hohe CPU-Last</a></td></tr></tbody></table><h3 id="altere-fehler" tabindex="-1">Ältere Fehler <a class="header-anchor" href="#altere-fehler" aria-label="Permalink to &quot;Ältere Fehler&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Was du siehst</th><th>Behoben in</th><th>Quelle</th></tr></thead><tbody><tr><td>„Cannot load jsonConfig of sourceanalytix: Not exists“</td><td>v0.4.9</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/453" target="_blank" rel="noreferrer">#453</a></td></tr><tr><td>Werte werden nachts auf 0 gesetzt oder verdoppeln sich (Quell-Datenpunkt mit Standardwert 0)</td><td>v0.4.8</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/210" target="_blank" rel="noreferrer">#210</a></td></tr><tr><td>Tageswerte werden um Mitternacht nicht auf 0 gesetzt, wenn sich der Quellwert nicht ändert</td><td>v0.5.0</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/478" target="_blank" rel="noreferrer">#478</a></td></tr><tr><td>Der Ordner des neuen Jahres wird nicht angelegt</td><td>v0.5.0</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/481" target="_blank" rel="noreferrer">#481</a></td></tr><tr><td>Die Reset-Erkennung greift nicht oder meldet Resets trotz Abschaltung</td><td>v0.5.0</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/686" target="_blank" rel="noreferrer">#686</a>, <a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/794" target="_blank" rel="noreferrer">#794</a></td></tr><tr><td>Der Grundpreis wird nach einem Neustart doppelt gezählt</td><td>v0.5.4</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1188" target="_blank" rel="noreferrer">#1188</a></td></tr><tr><td>Ein verpasster Periodenwechsel wird erst mit einem Neustart nachgeholt</td><td>v0.5.5</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/905" target="_blank" rel="noreferrer">#905</a></td></tr><tr><td>Vorperioden erscheinen in Flot, History oder Grafana einen Tag zu spät</td><td>v0.5.5</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/497" target="_blank" rel="noreferrer">#497</a></td></tr><tr><td>Ein kurzer Sprung auf 0 oder einen kleineren Wert gilt sofort als Reset, der Verbrauch verdoppelt sich</td><td>v0.6.0</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1199" target="_blank" rel="noreferrer">#1199</a></td></tr><tr><td>Preisdefinition und Einheit bleiben in Admin 8 leer</td><td>v0.6.0</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1202" target="_blank" rel="noreferrer">#1202</a></td></tr><tr><td>Ein kurzer Ausreißer nach unten mit Rückkehr zum alten Stand wird als Reset bestätigt</td><td>v0.6.1</td><td><a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1227" target="_blank" rel="noreferrer">#1227</a></td></tr></tbody></table><p>Die vielen alten Meldungen zu Tages-, Wochen- und Monatswechseln aus den Versionen 0.2 bis 0.4 sind mit dem Umbau in v0.5.0 erledigt. Wer noch eine dieser Versionen nutzt, sollte mindestens auf v0.5.0 aktualisieren, besser auf die aktuelle Version.</p><p><strong>Ab v0.7.0:</strong> Die Instanz-Einstellungen bekommen die Tabs „Übersicht“ und „Probleme“. Viele Fehler dieser Seite zeigt der Tab „Probleme“ direkt mit einem Knopf zur Lösung. Dafür braucht SourceAnalytix Admin 8.0.0 oder neuer (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1269" target="_blank" rel="noreferrer">#1269</a>).</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Wie aktualisiere ich SourceAnalytix?</a> · <a href="./log-meldungen#error-unit-not-supported-no">Log-Meldungen und Fehler beim Einrichten</a></p>',70)])])}const m=t(a,[["render",s]]);export{g as __pageData,m as default};
